## winsorzie the variable at 1% and 99% level.
winsor2 = function(data,vars,groups,pct){
  for (var in vars){
    for ( group in unique(data[,groups])){
      {
        data[which(data[,var]<=quantile(data[which(data[,groups]==group),var],na.rm=TRUE,pct)&data[,groups]==group),var] = quantile(data[which(data[,groups]==group),var],na.rm=TRUE,pct)
        data[which(data[,var]>=quantile(data[which(data[,groups]==group),var],na.rm=TRUE,1-pct)&data[,groups]==group),var] = quantile(data[which(data[,groups]==group),var],na.rm=TRUE,1-pct)
      }}
  }
  return(data)}

